document.addEventListener('change',e=>{if(e.target.id==='music-select'){setMusicTrack(e.target.value);unlockAudio()}if(e.target.id==='music-shuffle'){shuffleMusic=e.target.checked;localStorage.setItem('tt-shuffle',shuffleMusic);musicQueue=[];if(musicTrack)musicTrack.loop=!shuffleMusic}});
