document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='setup'){tone();if(savedVoyage())modal('<h2>Return to your local voyage?</h2><p>A voyage is already saved on this device.</p><div class="action-buttons" style="margin-top:25px"><button class="primary" data-action="resume-local">Resume voyage</button><button class="ghost" data-action="new-local">Start a new voyage</button></div>');else{custom=false;chooseOffers();setup()}}else if(a==='resume-local'){$('#overlay-root').innerHTML='';resume()}else if(a==='new-local'){forgetVoyage();$('#overlay-root').innerHTML='';custom=false;offers=[];chooseOffers();setup()}else if(a==='online'){const room=localStorage.getItem('tt-online-room');if(room)modal(`<h2>Rejoin your online room?</h2><p>Your captain may still be at sea in room <strong>${esc(room)}</strong>.</p><div class="action-buttons" style="margin-top:25px"><button class="primary" data-action="rejoin-online" data-room="${esc(room)}">Rejoin room</button><button class="ghost" data-action="abandon-online">Abandon it</button></div>`);else location.href='online.html'}else if(a==='player-profile')location.href='online.html?view=profile';else if(a==='rejoin-online')location.href=`online.html?room=${encodeURIComponent(b.dataset.room)}`;else if(a==='abandon-online'){localStorage.removeItem('tt-online-room');location.href='online.html'}else if(a==='home')intro();else if(a==='rules')rules();else if(a==='sound'){audioSettings()}else if(a==='custom'){custom=!custom;setup()}else if(a==='reroll'){chooseOffers();setup()}else if(a==='close')$('#overlay-root').innerHTML='';else if(a==='start')start();if(b.dataset.mode){playMode=b.dataset.mode;custom=false;setup()}if(b.dataset.total){playerCount=+b.dataset.total;humanCount=Math.min(humanCount,playerCount);setup()}if(b.dataset.humans){humanCount=+b.dataset.humans;setup()}if(b.dataset.power){chosen=b.dataset.power;setup()}});
document.addEventListener('input',e=>{if(e.target.id==='captain-name'){if(e.target.value.trim())localStorage.setItem('tt-name',e.target.value.trim());else localStorage.removeItem('tt-name')}if(e.target.dataset.localName!==undefined)localNames[+e.target.dataset.localName]=e.target.value});
document.addEventListener('change',e=>{if(e.target.dataset.slot!==undefined){const slot=+e.target.dataset.slot;if(slot===0)chosen=e.target.value;else assignments[slot-1]=e.target.value;setup()}if(e.target.dataset.passSlot!==undefined){passAssignments[+e.target.dataset.passSlot]=e.target.value;setup()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#overlay-root').innerHTML=''});
function particles(){const c=$('#atmosphere'),ctx=c.getContext('2d');let w,h;const motes=Array.from({length:40},()=>({x:Math.random(),y:Math.random(),r:Math.random()*1.8+.3,v:Math.random()*.00012+.00003}));function resize(){w=c.width=innerWidth;h=c.height=innerHeight}resize();addEventListener('resize',resize);let last=0;function frame(t){requestAnimationFrame(frame);if(t-last<40||matchMedia('(prefers-reduced-motion: reduce)').matches)return;last=t;ctx.clearRect(0,0,w,h);for(const p of motes){p.y-=p.v*40;if(p.y<0)p.y=1;ctx.fillStyle=`rgba(232,190,105,${.1+p.r*.17})`;ctx.beginPath();ctx.arc(p.x*w+Math.sin(t*.0002+p.y*6)*20,p.y*h,p.r,0,Math.PI*2);ctx.fill()}}requestAnimationFrame(frame)}
const [am,cm]=await Promise.all([fetch('assets/manifest.json',{cache:'no-cache'}).then(r=>r.json()),fetch('catalog.json',{cache:'no-cache'}).then(r=>r.json())]);assets=am;catalog=cm.powers;for(const [key,src] of Object.entries(assets)){if(key.startsWith('cards/')){const img=new Image();img.src=src;img.decode().catch(()=>{})}}if(onlineMode)connectOnlineGame();else intro();particles();

function connectOnlineGame(){
 const credential=localStorage.getItem('tt-online-credential'),device=localStorage.getItem('tt-device-id');if(!credential||!device){location.href='online.html';return}
 screen.innerHTML='<main class="game"><p class="loading-text">Rejoining the online fleet…</p></main>';const api=ONLINE_API.replace('https','wss');onlineSocket=new WebSocket(`${api}/api/rooms/${encodeURIComponent(onlineRoom)}/ws?deviceId=${encodeURIComponent(device)}`,`tt-auth.${credential}`);
 onlineSocket.onmessage=e=>{const message=JSON.parse(e.data);if(message.type==='error'){toast(message.message);return}if(message.type!=='state')return;onlineRoomState=message.state;if(message.state.phase==='lobby'){location.href=`online.html?room=${encodeURIComponent(onlineRoom)}`;return}state=message.state.snapshot;session=`online:${onlineRoom}`;busy=false;renderGame();startOnlineTimer()};
 onlineSocket.onclose=()=>{toast('Connection lost. Rejoining…');setTimeout(()=>onlineMode&&connectOnlineGame(),1800)};onlineSocket.onerror=()=>toast('The online harbor is not responding.');
}
function onlineSend(data){if(onlineSocket?.readyState===WebSocket.OPEN)onlineSocket.send(JSON.stringify(data))}
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action="return-online-home"]'))onlineSend({type:'leave'})},{capture:true});
function startOnlineTimer(){
 clearInterval(onlineTimer);
 const update=()=>{
  if(!onlineMode||!state?.request)return;
  const now=Date.now(),pending=!!onlineRoomState?.resolutionPending,locked=Math.max(0,(onlineRoomState?.drawAllowedAt||0)-now),left=Math.max(0,(onlineRoomState?.turnDeadline||0)-now),kind=state.request.kind,bot=onlineRoomState?.timerOwner==='bot',mode=onlineRoomState?.timerMode,seconds=Math.ceil((locked>0?locked:left)/1000);
  let label='';
  if(pending)label='Resolving card…';
  else if(locked>0)label=`Next draw in ${seconds}s`;
  else if(left>0)label=bot&&mode==='slow'?`Bot draws in ${seconds}s`:bot&&mode==='controlled'?`Host may draw · automatic in ${seconds}s`:`Draw now · automatic in ${seconds}s`;
  else if(['turn','bot-turn','online-turn','waiting','bot-waiting'].includes(kind))label='Drawing…';
  document.querySelectorAll('.shared-countdown').forEach(e=>e.textContent=label);
  document.querySelectorAll('[data-answer],[data-action="next"]').forEach(button=>{
   const labeled=button.dataset.fixedAction==='advance',turnClock=['turn','bot-turn','online-turn','waiting','bot-waiting'].includes(kind),isDraw=turnClock&&(labeled||button.dataset.action==='next'||['bot-turn','online-turn'].includes(kind)&&button.dataset.answer!==undefined&&button.textContent.toLowerCase().includes('draw'));
   if(!isDraw)return;
   const unavailable=button.dataset.unavailable==='true';
   button.disabled=presenting||busy||pending||locked>0||unavailable||['bot-waiting','waiting'].includes(kind);
   // Never replace the draw-pile contents: only the labeled command button
   // receives the visible countdown.
   if(labeled){
    const drawer=state.game?.players?.[state.request.drawer],base=bot?(mode==='controlled'?`Draw for ${drawer?.name||'bot'}`:'Bot draws'):(drawer?.name?`${drawer.name} draws`:'Draw card');
    button.textContent=pending?'Resolving…':locked>0?`${base} · ${Math.ceil(locked/1000)}s`:left>0?`${base} · ${Math.ceil(left/1000)}s`:base;
   }
  });
  const liveTurn=['turn','bot-turn','online-turn','waiting','bot-waiting'].includes(kind),deadline=onlineRoomState?.turnDeadline||0;
  if(!pending&&liveTurn&&(!deadline||now>=deadline)){const key=state.request.id+':'+(deadline||'repair');if(onlineTickKey!==key){onlineTickKey=key;onlineSend({type:'tick',requestId:state.request.id})}}
 };
 update();onlineTimer=setInterval(update,150)
}
function onlineChat(){const messages=onlineRoomState?.chat||[],quick=['😀','😂','😡','😢','😕','😴','😱','👍'];modal(`<div class="eyebrow">ONLINE ROOM ${esc(onlineRoom)}</div><h2>Fleet chat</h2><div class="online-game-chat">${messages.map(m=>`<p><strong>${esc(m.username)}</strong> ${esc(m.text)}</p>`).join('')||'<p>No messages yet.</p>'}</div><div class="quick-chat" aria-label="Quick reactions">${quick.map(message=>`<button type="button" data-quick-chat="${message}" aria-label="Send ${message}">${message}</button>`).join('')}</div><div class="online-chat-send"><input id="online-chat-input" maxlength="240" placeholder="Message the fleet"><button class="primary" data-action="send-online-chat">Send</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='online-chat')onlineChat();if(a==='send-online-chat'){const input=$('#online-chat-input');if(input?.value.trim()){onlineSend({type:'chat',message:input.value.trim()});input.value='';$('#overlay-root').innerHTML=''}}if(a==='reveal-tide-secret')revealSecret(+b.dataset.secretId);if(onlineMode&&a==='leave-game'){e.preventDefault();e.stopImmediatePropagation();modal('<h2>Leave the online voyage?</h2><p>You can reconnect from this device while the room remains available. A bot takes over if you disconnect.</p><div class="action-buttons" style="margin-top:25px"><button class="ghost" data-action="close">Keep playing</button><button class="primary" data-action="return-online-home">Return to online harbor</button></div>')}if(a==='return-online-home'){onlineSocket?.close();location.href='online.html'}},true);

const cardNames={coin:'Glimmering Coin',crate:'Loot Crate',diamond:'Diamond Necklace',crown:'Golden Crown',coin_curse:'Cursed Coin',idol:'Cursed Idol',surge:'Storm Surge',whirlpool:'Whirlpool',marooned:'Marooned',rudder:'Broken Rudder',escape:'Escape Ship',trick:'Tempest Trick',prophecy:'Parrot’s Prophecy',wave:'Wild Wave',siren:'Siren’s Song',key:'Enchanted Key',chest:'Enchanted Chest',echo:'Echo of the Deep',cannon:'Cannon Fire'};
const cardRules={coin:'Add 10 gold to the shared pot.',crate:'Add 20 gold to the shared pot.',diamond:'Add 30 gold to the shared pot.',crown:'Add 100 gold to the shared pot.',coin_curse:'Subtract 10 gold from the pot, never below zero.',idol:'Subtract 50 gold from the pot, never below zero.',surge:'Double the pot. If it is empty, put 100 gold into it.',whirlpool:'Every unprotected captain still in the storm sinks and loses a ship. Escape Ship saves half the pot.',marooned:'Lose one ship, leave the round, and collect half the pot. An Escape Ship saves the other half.',rudder:'Immediately harbor, then lose 30 gold. Mechanic ignores this card.',escape:'Keep this card beside your power. If you sink, save half the pot. If you harbor, earn 20 extra gold. Only one active Escape Ship per captain.',trick:'Take 20 gold for yourself and subtract up to 20 from the shared pot. Keep the card out of the deck until round end.',prophecy:'Privately inspect the next two cards. Rearrange them, optionally putting one on the bottom.',wave:'Earn 10 gold. Shuffle the discard pile into the draw pile. The next draw is safe. Held cards stay out.',siren:'Nobody—including Siren Queen—can voluntarily harbor until four more cards have been drawn. Siren Queen is immune to hazards while the Song lasts. A new Song replaces the previous duration.',key:'The next draw is safe. Siren Queen can collect this card when she or a neighbor draws it.',chest:'The next draw is safe. Siren Queen can collect this card when she or a neighbor draws it.',echo:'Copy the last resolved card effect. While Navigator remains in the storm, Navigator may instead choose the second-most-recent effect.',cannon:'Choose one other eligible captain still in the storm. They must harbor. Cannoneer is immune and fires at everyone when drawing this card. After a captain is forced out, all remaining captains must stay for one more draw. Cannon tokens do not impose this restriction.'};
const powerRules={
'Tempest King':'Start with 8 ships. Whenever anyone draws Storm Surge outside safe waters, become immune to Whirlpool and Marooned for the next two table-wide draws. Another Surge refreshes protection. Bots stay for protected draws; a human captain may choose to harbor.',
'Merchant':'Start with 6 ships. Gain 20 extra gold whenever you harbor, including forced harboring. At game end, each remaining ship sells for 60 gold instead of 30.',
'Siren Queen':'Start with 7 ships. Collect Keys and Chests drawn by you or your two immediate neighbors. Each pair immediately grants a life, up to 8. Unmatched pieces carry between rounds. Collect their Diamond Necklaces too, worth 30 extra gold each at game end. Card effects still happen. You may harbor during Siren’s Song; you are not immune to hazards.',
'Undead Admiral':'Start with 6 ships and no Plunder tokens. Gain one at the beginning of rounds 6 and 11. Spend at most one per round when another captain sinks to gain half the pot. You can plunder after harboring and never plunder yourself. After you harbor, curses subtract an additional 10 gold that round. Spare tokens are worth 10 gold.',
'Mechanic':'Start with 6 ships and 3 repair tokens. Use one when sinking to prevent a life loss, or sell one to another sinking captain for 150 gold. Repairs do not keep a captain in the round. Ignore Broken Rudder. Spare repair tokens are worth 30 gold.',
'Tide Watcher':'Start with 6 ships. Before Calm Waters, privately draw a card. A treasure earns you its printed gold immediately. Otherwise hold it, and place it on top of the deck while still in the storm. Gain a Tide token whenever Wild Wave resolves outside Calm Waters. Spare Tide tokens are worth 15 gold.',
'Navigator':'Start with 6 ships and 5 tokens. Use at most one token per round to ignore hazards for three table-wide draws. While still in the storm, choose which of the previous two resolved card effects any Echo copies. Blocking hazards earns no money. Spare tokens are worth 10 gold.',
'Cannoneer':'Start with 7 ships and no cannon tokens. Gain a token whenever you personally draw Cannon Fire. A token forces one other eligible captain to harbor, without an extra required draw. Your own Cannon Fire forces all other active captains to harbor. Ignore Cannon Fire. Treasure you draw alone in the storm is doubled. Spare tokens are worth 10 gold.',
'Blood Sailor':'Start with 6 ships. Your two starting neighbors remain your targets throughout the game. Gain 40 gold each time either sinks, even if repaired. Gain one life the first time each target falls to exactly 1 ship; this can bring you back next round.',
'Storm Warden':'Start with 7 ships and 3 tokens. When you sink, spend a token to save half the pot, without preventing life loss. A token, Marooned, and Escape Ship each recover half; any two recover the full pot, never more. Marooned still costs a ship. Spare Warden tokens are worth 10 gold.',
'Cursed Captain':'Start with 6 ships. Collect curses drawn by yourself and your immediate neighbors: 10 gold per Cursed Coin, 50 per Cursed Idol. Your own curse draws never reduce the pot. Neighbors’ curses still do. No collection limit, no bonus lives; collected curses return at round end.',
'Parrot Whisperer':'Start with 6 ships and 4 tokens. Gain one token whenever anyone draws Parrot’s Prophecy, including yourself, up to 10 held. Spend a token to inspect and rearrange the top two cards, optionally placing one on the bottom. Token use does not generate a new token. Spare tokens are worth 15 gold.'};
Object.assign(cardNames,Object.fromEntries(Object.entries(expansionCards).map(([k,v])=>[k,v.name])));
Object.assign(cardRules,Object.fromEntries(Object.entries(expansionCards).map(([k,v])=>[k,v.rule])));
cardRules.key=cardRules.chest='The next draw is safe. Siren Queen collects this card only when she or one of her immediate neighbors draws it. Each Key–Chest pair immediately restores one ship (maximum 8 ships), then that pair is returned.';
Object.assign(powerRules,updatedPowerRules);
let autoRound=null,roundSpeed=1;
let pollTimer=null,lastEvent=0,lastChoice=null,lastPot=0,revealing=false;
const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:1});
function tokenDots(n){return `<div class="tokens" title="${n} tokens">${Array.from({length:Math.min(n,10)},()=>'<i class="token-dot"></i>').join('')}${n>10?`<span>+${n-10}</span>`:''}</div>`}
function heldCards(p,human=false){return `<div class="held-cards">${p.secret?`<button class="held-card secret-held" data-secret-owner="${p.id}" title="Tide Watcher holds a secret card"><img src="${image('cards','back')}" alt="Secret card, face down"></button>`:''}${p.held.map(c=>`<button class="held-card" data-card="${c.physical}" data-effect="${c.effect}" title="${esc(cardNames[c.effect])}${c.physical!==c.effect?' (Echo copy)':''}"><img src="${image('cards',c.physical)}" alt="${esc(cardNames[c.effect])}">${c.physical!==c.effect?'<span class="copy-mark">↪</span>':''}</button>`).join('')}${!p.held.length&&!p.secret?'<span class="empty-held">No collected cards</span>':''}</div>`}
const shipIcon='<img class="ship-icon" src="assets/ship.svg" alt="">';
let logOpen=false,logRound=null;
let presenting=false,presentationKey=0,displayPot=0,fleetPositions=new Map(),handoffReady=null;
const viewerId=g=>Number.isInteger(g?.viewer)?g.viewer:0;
const isPassPlay=g=>(g?.humanPlayers?.length||0)>1;
const privateDecision=r=>!!r&&(['tide-secret','prophecy','prophecy-order','spyglass','spyglass-pick','spyglass-order','parrot'].includes(r.kind)||r.kind.startsWith('spyglass')||r.kind.startsWith('prophecy'));
const needsHandoff=()=>!onlineMode&&isPassPlay(state?.game)&&privateDecision(state?.request)&&state?.request?.player!==undefined&&handoffReady!==state.request.id;
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const delay=ms=>new Promise(r=>setTimeout(r,reduced()?30:playbackDuration(ms)));
const statusName=p=>p.status==='active'?'IN THE STORM':p.status==='harbor'?'IN HARBOR':p.ships===0?'ELIMINATED':'SUNK · OUT THIS ROUND';
function stabilizeFleetOrder(g){const count=g.players.length,h=g.seating.indexOf(0),order=[0,...g.seating.slice(h+1),...g.seating.slice(0,h)];for(const p of g.players){const el=document.querySelector(`[data-ship="${p.id}"]`);if(!el)continue;const i=order.indexOf(p.id),angle=-Math.PI/2+i*Math.PI*2/count,docked=p.status==='harbor',charmed=g.song&&p.status==='active'&&p.power!=='Siren Queen',sx=71+(charmed?16:20)*Math.cos(angle),sy=52+(charmed?22.4:28)*Math.sin(angle),x=docked?24.5:sx,y=docked?dockYFor(i,count):sy;el.dataset.x=x;el.dataset.y=y;el.dataset.seaX=sx;el.dataset.seaY=sy;el.style.left=x+'%';el.style.top=y+'%'}}
function profileActions(p,r,g){if(!g.sharedDevice||!g.humanPlayers.includes(p.id)||r?.kind!=='shared-turn')return '';const options=r.options||[],buttons=options.map((o,i)=>o.player===p.id?`<button class="${o.action==='harbor'?'harbor-button':''}" data-answer="${i}">${esc(o.label)}</button>`:'').join('');return buttons?`<div class="captain-actions">${buttons}</div>`:''}
function chatBubble(p){if(!onlineMode||!p.human)return '';const member=onlineRoomState?.members?.[p.id],message=[...(onlineRoomState?.chat||[])].reverse().find(m=>m.accountId===member?.accountId);return message&&Date.now()-(message.at||0)<9000?`<div class="captain-chat">${esc(message.text)}</div>`:''}
function opponentCard(p,current,seat,req,g){const viewer=viewerId(state?.game),local=g?.sharedDevice&&g.humanPlayers.includes(p.id),next=p.id===current&&p.status==='active',label=p.human?(local?esc(p.name):p.id===viewer?`YOU · ${esc(p.name)}`:esc(p.name)):'BOT';return `<article data-captain="${p.id}" class="captain ${p.id===viewer?'human-captain':''} ${p.status==='active'?'sailing':p.status==='harbor'?'docked':'sunk'} ${next?'drawing':''}" style="--seat:${seat}">${chatBubble(p)}<div class="captain-head"><button class="portrait-button" data-profile="${p.id}" aria-label="View ${esc(p.power)} power"><img src="${image('portraits',p.power)}" alt="${esc(p.power)}"></button><div><div class="captain-name">${label}${next?' · NEXT TO DRAW':''}</div><h3>${esc(p.power)}</h3><div class="ship-count">${shipIcon}${p.ships}<span>${p.ships===1?'ship':'ships'}${p.immortal?' · Indestructible':''}</span></div></div></div><div class="captain-resources">${tokenDots(p.tokens)}${witchTokens(p)}</div>${heldCards(p)}${profileActions(p,req,g)}<div class="captain-status"><span>${statusName(p)}</span>${p.songProtected?'<span class="shield">Song · hazard immunity</span>':''}${p.protection?`<span class="shield">◈ ${p.protection} protected draws</span>`:''}${!onlineMode&&p.harborGold!=null?`<b>Collected ${fmt(p.harborGold)} gold</b>`:''}</div></article>`}
function weatherMarkup(g){return `<div class="map-weather ${g.safe?'calm':'storm'}"><span class="weather-mark">${g.safe?'☀':g.song?'♫':'≋'}</span><div><strong>${g.safe?'CALM WATERS':g.song?'SIREN’S SONG':'IN THE STORM'}</strong><p>${g.safe?`${g.safeRemaining||1} safe draw${(g.safeRemaining||1)>1?'s':''} · No harboring · Card effects are off`:g.song?`${g.song} draws remaining · Harboring is locked for everyone`:'Normal card effects and powers are active'}</p></div></div>`}
function fleetMarkup(g){const h=g.seating.indexOf(0),order=[0,...g.seating.slice(h+1),...g.seating.slice(0,h)];return `<section class="fleet-board ${g.safe?'calm-sea':'rough-sea'} ${g.song?'song-active':''}" aria-label="Fleet positions">${mapImage()}${seaWaves()}<div class="fleet-heading"><span></span><span>${g.players.filter(p=>p.status==='active').length} still sailing</span></div>${order.map((id,i)=>{const p=g.players[id],angle=-Math.PI/2+i*Math.PI*2/order.length,docked=p.status==='harbor',sunk=p.status!=='active'&&!docked,hx=24.5,hy=dockYFor(i,order.length),charmed=g.song&&p.status==='active'&&p.power!=='Siren Queen',sx=71+(charmed?16:20)*Math.cos(angle),sy=52+(charmed?22.4:28)*Math.sin(angle),x=docked?hx:sx,y=docked?hy:sy;return `<span class="harbor-berth" style="left:${hx}%;top:${hy}%" aria-hidden="true"></span><button class="fleet-ship ${docked?'at-harbor':sunk?'lost-ship':'at-sea'} ${p.id===g.current&&p.status==='active'&&g.phase==='sailing'?'current-ship':''}" data-profile="${p.id}" data-ship="${p.id}" data-x="${x}" data-y="${y}" data-sea-x="${sx}" data-sea-y="${sy}" style="left:${x}%;top:${y}%" aria-label="${esc(p.name)}: ${statusName(p)}"><span class="ship-bob">${shipIcon}</span>${charmed?'<span class="siren-dizzy" aria-label="Entranced by Siren’s Song">✧ · ✦</span>':''}<span class="mini-cannon"></span><span class="ship-bubble ${x>75?'align-right':x<35?'align-left':''}"><img src="${image('portraits',p.power)}" alt=""><strong>${esc(p.name)}</strong><small>${statusName(p)}</small></span></button>`}).join('')}${rowboatsMarkup(g,order)}<div class="siren-chorus" aria-hidden="true"><img src="assets/sirens-rocks.png" alt="">${Array.from({length:14},(_,i)=>{const a=Math.random()*Math.PI*2;return `<i class="siren-note" style="--note-x:${Math.cos(a)*(65+Math.random()*60)}px;--note-y:${Math.sin(a)*(45+Math.random()*35)}px;--note-delay:${-Math.random()*5}s;--note-duration:${2+Math.random()*3}s">${i%2?'♪':'♫'}</i>`}).join('')}</div></section>`}
function resolutionMarkup(g){const r=g.resolution;if(!r)return '<div class="outcome-empty">The sea is quiet.<br><span>The next card’s result will appear here.</span></div>';return `<div class="outcome-title"><span class="eyebrow">LAST DRAW · ${esc(g.players[r.player].name)}</span><h3>${esc(cardNames[r.card])}${r.safe?' <small>SAFE DRAW</small>':''}</h3></div><ul>${r.lines.slice(1).map(t=>`<li class="${/Cannon|leaves the storm|sinks|marooned/.test(t)?'important-outcome':''}">${esc(t)}</li>`).join('')||'<li>Card resolved. The fleet makes its next decision.</li>'}</ul>`}
function commandCopy(g,r){const from=g.phase==='round-end'?g.roundStarter:g.current,next=['resolving','round-end'].includes(g.phase)?[...g.seating.slice(g.seating.indexOf(from)+1),...g.seating.slice(0,g.seating.indexOf(from)+1)].find(id=>g.phase==='round-end'?g.players[id].ships>0:g.players[id].status==='active'):undefined;const drawer=g.players[r?.drawer??next??g.current],water=g.safe?'CALM WATERS':g.song?'SIREN’S SONG':'IN THE STORM';return `<div class="decision-copy"><h3>${esc(drawer.name)} draws next</h3><div class="command-meta"><strong>${water}</strong><button class="water-info" data-action="water-info" aria-label="Explain Calm Waters">i</button>${onlineMode?'<span class="shared-countdown"></span>':''}</div>${g.resolution?`<button class="last-result" data-action="last-result">Last draw: ${esc(cardNames[g.resolution.card])} · View what happened ↗</button>`:'<span class="last-result empty-last">No card drawn this round</span>'}</div>`}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="water-info"]'))modal(`<h2>Calm Waters</h2><p>The first three draws of each round are safe. Nobody can harbor, and normal effects and player powers do not activate.</p><p>Treasures add their printed gold, hazards add 50 gold, curses add nothing, and other cards add 10 gold. Afterward, the storm begins and normal effects return. Some cards, such as Enchanted Key and Enchanted Chest, can introduce more Calm Waters during the round.</p>`)});

