document.addEventListener('click',e=>{const button=e.target.closest('[data-action="handoff-ready"]');if(!button||!state?.request)return;handoffReady=state.request.id;$('#overlay-root').innerHTML='';lockControls();const special=!['turn','shared-turn','online-turn','round','round-end'].includes(state.request.kind);if(special){lastChoice=state.request.id;showChoice()}else scheduleAutoDraw()});
