   return ship.animate([{transform:`translate(${ox}px,${oy}px) rotate(0deg) scale(1)`,opacity:1},{transform:`translate(${ox*.55+dx*.45-(dy-oy)*.3}px,${oy*.55+dy*.45+(dx-ox)*.3}px) rotate(95deg) scale(.85)`,opacity:1,offset:.4},{transform:`translate(${dx+dy*.12}px,${dy-dx*.12}px) rotate(240deg) scale(.4)`,opacity:.8,offset:.8},{transform:`translate(${dx}px,${dy}px) rotate(360deg) scale(0)`,opacity:0}],{duration:playbackDuration(2000),easing:'ease-in',fill:'forwards'});
