async function cannonEffect(e){const board=$('.fleet-board'),source=$(`[data-ship="${e.source}"]`),target=$(`[data-ship="${e.target}"]`);if(!board||!source||!target)return;const br=board.getBoundingClientRect(),a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),sx=a.left-br.left+a.width/2,sy=a.top-br.top+a.height/2,tx=b.left-br.left+b.width/2,ty=b.top-br.top+b.height/2;source.style.setProperty('--cannon-angle',Math.atan2(ty-sy,tx-sx)*180/Math.PI+'deg');source.classList.add('firing');const ball=document.createElement('i');ball.className='cannonball';ball.style.left=sx+'px';ball.style.top=sy+'px';board.appendChild(ball);tone('cannon');if(!reduced())await ball.animate([{transform:'translate(0,0)'},{transform:`translate(${(tx-sx)*.5}px,${(ty-sy)*.5-32}px)`},{transform:`translate(${tx-sx}px,${ty-sy}px)`}],{duration:playbackDuration(650),easing:'ease-in'}).finished;ball.remove();const splash=document.createElement('span');splash.className='cannon-splash';splash.style.left=tx+'px';splash.style.top=ty+'px';splash.innerHTML='<i></i><i></i><i></i><i></i><i></i>';board.appendChild(splash);tone('splash');source.classList.remove('firing');announce([`${state.game.players[e.source].name} fires at ${state.game.players[e.target].name} — to harbor!`]);await delay(400);moveFleetShip(target);await delay(500);splash.remove()}
