async function countPot(target,reset=false){const from=displayPot,diff=target-from;const digits=[...document.querySelectorAll('.digit')];if(!digits.length)return;const draw=n=>{const str=String(Math.min(9999,Math.max(0,Math.floor(n)))).padStart(4,'0');digits.forEach((el,i)=>{if(el.dataset.value!==str[i]){el.dataset.value=str[i];el.querySelectorAll('b').forEach(b=>b.textContent=str[i]);el.classList.remove('tick');void el.offsetWidth;el.classList.add('tick')}})};if(!diff){draw(target);return}const change=$('.pot-change');if(change&&!reset){change.textContent=`${diff>0?'+':''}${fmt(diff)} GOLD`;change.className='pot-change '+(diff>0?'gain':'loss')};if(reset&&change){change.textContent='';change.className='pot-change'}if(diff>0&&!reset)tone('coins');await new Promise(resolve=>{const start=performance.now(),duration=reduced()?0:680;function step(t){const f=duration?Math.min(1,(t-start)/duration):1;draw(from+diff*(1-Math.pow(1-f,3)));if(f<1)requestAnimationFrame(step);else resolve()}requestAnimationFrame(step)});displayPot=target;lastPot=target}
function cardSound(d){if(d.card==='prophecy'&&!d.safe)return 'parrot';const e=d.effect||d.card;const treasure={coin:1,crate:2,diamond:3,crown:4,fortune:5}[e];if(treasure)return 'treasure-'+treasure;if(d.safe)return 'draw';return ({coin_curse:'gloom-1',idol:'gloom-2',spoils:'gloom-3'})[e]||e;}
async function reveal(d){const preload=new Image();preload.src=image('cards',d.card);document.querySelector('.reveal-stage')?.remove();const value={coin:10,crate:20,diamond:30,crown:100,fortune:200,coin_curse:10,idol:50,spoils:100}[d.effect||d.card]||0,treasure=['coin','crate','diamond','crown','fortune'].includes(d.effect||d.card),curse=!d.safe&&['coin_curse','idol','spoils'].includes(d.effect||d.card),tier=treasure?({coin:1,crate:2,diamond:3,crown:4,fortune:5}[d.effect||d.card]||1):value>=100?3:value>=30?2:1;const fortune=d.card==='fortune'||(!d.safe&&d.effect==='fortune'),effect=fortune?'fortune':d.safe?'safe':d.effect||d.card,el=document.createElement('div');el.className=`reveal-stage cinematic ${effect} ${treasure?"treasure-reveal":curse?"curse-reveal":""} intensity-${tier}`;el.style.setProperty("--intensity",tier);const safeValue={coin:10,crate:20,diamond:30,crown:100,fortune:200,spoils:0,whirlpool:50,marooned:50,coin_curse:0,idol:0}[d.card]??10;el.innerHTML=`<div class="effect-rings"></div><div class="effect-particles">${Array.from({length:treasure||curse?8+tier*12:24},(_,i)=>`<i style="--i:${i};--r:${15+(i*37)%75}deg"></i>`).join('')}</div>${effect==='surge'?'<div class="surge-halo"></div><div class="surge-banner">THE TREASURE RISES</div>':''}${fortune?'<div class="fortune-sunburst" aria-hidden="true"></div><div class="fortune-banner">A LEGEND UNEARTHED <strong>200 GOLD</strong></div>':''}<div class="reveal-caption">${esc(state.game.players[d.player].name)} DREW</div><img class="reveal-card" src="${image('cards',d.card)}" alt="${esc(cardNames[d.card])}"><div class="reveal-title">${esc(cardNames[d.card])}</div>${d.card==='echo'&&!d.deferSound&&!d.safe?`<div class="echo-reveal-copy">Copying ${esc(cardNames[d.effect]||'no previous card')}</div>`:''}${blockMarkup(d)}<div class="reveal-sub">${d.safe?`CALM WATERS · +${safeValue} GOLD<br>No normal effect. No power activation.`:'Resolving its effect…'}</div>`;document.body.appendChild(el);if(!d.deferSound)tone(cardSound(d));await dismissible(el,fortune?2600:1800);el.classList.add('depart');await delay(220);el.remove()}
async function whirlpoolAdded(round){const el=document.createElement('div');el.className='storm-arrival';el.innerHTML=`<div class="storm-arrival-content"><span class="eyebrow">ROUND ${round} · THE SEA GROWS STRONGER</span><h2>A new Whirlpool<br>joins the deck.</h2><img src="${image('cards','whirlpool')}" alt="New Whirlpool"><p>One more danger in Gold Reef Waters.</p><button class="primary">Shuffle it in</button></div>`;document.body.appendChild(el);tone('whirlpool');await new Promise(r=>el.querySelector('button').onclick=r);el.remove()}
async function shuffleDeck(){const el=$('.draw-pile');if(!el)return;el.classList.add('shuffling');tone('shuffle');await delay(1000);el.classList.remove('shuffling')}
function announce(lines){document.querySelector('.fleet-notices')?.remove();const el=document.createElement('div');el.className='fleet-notices';el.setAttribute('role','status');el.innerHTML=lines.map(t=>`<p>${esc(t)}</p>`).join('');$('.fleet-board')?.appendChild(el);if(lines.some(x=>/harbor/i.test(x)))tone('harbor');else tone('token');setTimeout(()=>el.remove(),6500)}

function showChoice(){const r=state?.request;if(!r||needsHandoff())return;if(r.kind==='spyglass-order'){showSpyglassOrder(r);return;}const player=state.game.players[r.player??viewerId(state.game)];modal(`<div class="choice-modal ${r.kind.startsWith('spyglass')?'spyglass-choice':''}"><div class="eyebrow">${esc(player.power)}</div><h2>${esc(r.kind==='plunder'?'Plunder the sunken fleet?':r.title)}</h2><p>${esc(r.detail)}</p>${r.cards?`<div class="large-cards">${r.cards.map(c=>`<img src="${image('cards',c)}" alt="${esc(cardNames[c])}">`).join('')}</div>`:''}<div class="choice-buttons">${r.options.map((o,i)=>`<button class="choice-option" data-answer="${i}">${o.cards?`<span class="mini-preview">${o.cards.map(c=>`<img src="${image('cards',c)}" alt="${esc(cardNames[c])}">`).join('')}${(o.bottom||[]).map(c=>`<img class="bottom-card" src="${image('cards',c)}" alt="Bottom: ${esc(cardNames[c])}">`).join('')}</span>`:''}${esc(o.label)}</button>`).join('')}</div></div>`)}
async function answer(index,skip=false,confirmed=false){const finishingRound=state?.request?.kind==='round-end';if(busy||presenting&&!finishingRound||needsHandoff()||!state?.request)return;if(finishingRound){presentationKey++;presenting=false}const request=state.request,option=request.options[index];if(!option)return;const captain=state.game.players[request.player??viewerId(state.game)];if(request.kind==='turn'&&captain.status!=='active'&&option.value==='stay')autoRound=state.game.round;if(option.value==='harbor'&&!skip&&!confirmed&&(captain.protection>0||captain.songProtected)){const requestId=request.id;modal(`<h2>You are still protected</h2><p>${captain.songProtected?'Siren’s Song is protecting you from hazard cards.':`You have ${captain.protection} protected card draw${captain.protection===1?'':'s'} remaining.`} You may harbor, but you could safely stay for more treasure. Do you really want to harbor?</p><div class="choice-buttons"><button class="primary" id="keep-sailing">Stay in the storm</button><button class="ghost" id="confirm-protected-harbor">Harbor anyway</button></div>`);$('#keep-sailing').onclick=()=>$('#overlay-root').innerHTML='';$('#confirm-protected-harbor').onclick=()=>{if(state.request?.id===requestId)answer(index,false,true)};return;}busy=true;$('#overlay-root').innerHTML='';tone();document.querySelectorAll('[data-answer],[data-action="next"]').forEach(b=>b.disabled=true);if(onlineMode){onlineSend({type:'action',requestId:request.id,value:option.value});setTimeout(()=>{if(busy){busy=false;lockControls()}},5000);return}try{const d=skip?await gameCall({type:'action',requestId:request.id,value:option.value,skip}):await choiceFlow.act(state,option.value,gameCall,d=>state=d);if(d.revision>=state.revision)state=d;busy=false;renderGame()}catch(e){busy=false;toast(e.message);renderGame()}}
function scheduleAutoDraw(){clearTimeout(pollTimer);if(roundSpeed===0||!canAutoDraw(state,autoRound)||busy||presenting)return;const id=state.request.id;pollTimer=setTimeout(()=>{if(roundSpeed!==0&&canAutoDraw(state,autoRound)&&state.request.id===id&&!busy&&!presenting){if($('#overlay-root').children.length){scheduleAutoDraw();return}const index=state.request.options.findIndex(o=>o.value==='stay');if(index>=0)answer(index)}},autoDrawDelay());}
function poll(){} // Worker actions return a complete, settled snapshot.
function scoresTable(g){return `<table class="score-table"><thead><tr><th>Captain</th><th>Ships</th><th>Gold</th></tr></thead><tbody>${[...g.players].sort((a,b)=>b.gold-a.gold).map((p,i)=>`<tr class="${p.id===0?'you-score':''}"><td>${i+1}. ${esc(p.power)}${p.id===0?' <span style="color:var(--teal)">· You</span>':''}</td><td>${p.ships}</td><td class="gold-value">${fmt(p.gold)}</td></tr>`).join('')}</tbody></table>`}
const victoryLines={'Tempest King':'The storm bows to its king.','Merchant':'Every voyage has its price. This one made a fortune.','Siren Queen':'The ocean’s richest song belongs to her.','Undead Admiral':'Even death cannot sink a legend.','Mechanic':'A fortune built one saved ship at a time.','Tide Watcher':'The tide has carried every treasure home.','Navigator':'The stars led straight to fortune.','Cannoneer':'The last cannon echoes over a sea of gold.','Blood Sailor':'Red sails. Golden spoils.','Storm Warden':'Through every storm, the treasure endured.','Cursed Captain':'Some curses are worth their weight in gold.','Parrot Whisperer':'A whispered secret. A legendary fortune.'};
Object.assign(victoryLines,newVictoryLines);
function stopEndSounds(){activeSounds.forEach(a=>{a.pause();a.currentTime=0});activeSounds.clear()}
function rivalLaugh(power){const female=['Sea Witch','Siren Queen','Navigator','Merchant','Storm Warden'].includes(power);const choices=female?['laugh-female-1','laugh-female-2']:['laugh-male'];tone(choices[Math.floor(Math.random()*choices.length)])}
async function recordOfflineResult(document){const credential=localStorage.getItem('tt-online-credential');if(!credential||!document||onlineMode)return;try{const response=await fetch(`${ONLINE_API}/api/account/offline-result`,{method:'POST',headers:{Authorization:`Bearer ${credential}`,'Content-Type':'application/json'},body:JSON.stringify({document})});if(response.ok){const data=await response.json();if(data.recorded)toast('Voyage added to your player profile.')}}catch{}}
function renderEnd(){const voyageDocument=savedVoyage(),g=state.game,best=Math.max(...g.players.map(p=>p.gold)),winners=g.players.filter(p=>p.gold===best),won=winners.some(p=>p.id===0),champ=won?g.players[0]:winners[0];$('#overlay-root').innerHTML='';document.querySelectorAll('.fleet-notices,.reveal-stage').forEach(e=>e.remove());screen.innerHTML=`<main class="victory-scene ${won?'won':'lost'}"><img class="victory-art" src="${image('victories',slug(champ.power))}" alt="${esc(champ.power)} celebrating among treasures"><div class="victory-shade"></div><div class="victory-coins" aria-hidden="true">${Array.from({length:38},(_,i)=>`<i style="--coin:${i};left:${(i*37)%100}%"></i>`).join('')}</div><div class="victory-content"><span class="eyebrow">${winners.length>1?'A SHARED LEGEND':won?'VICTORY IS YOURS':'THE VOYAGE IS COMPLETE'}</span><h1>${esc(champ.power)}<br><span>${won?'You claimed the fortune.':'Claims the fortune.'}</span></h1><p>${esc(victoryLines[champ.power])}</p><div class="victory-fortune"><span>WINNING FORTUNE</span><strong>${fmt(best)} <small>gold</small></strong></div><details class="victory-ledger"><summary>Final captain rankings</summary>${scoresTable(g)}</details><div class="action-buttons"><button class="primary" data-action="new-voyage">Sail again</button><button class="ghost" data-action="home">Return to shore</button></div></div></main>`;syncMusic(null,won?'victory':'loss');if(won)tone('coins');else rivalLaugh(champ.power);recordOfflineResult(voyageDocument);forgetVoyage();window.scrollTo(0,0)}

function profile(id){const p=state.game.players[id];modal(`<div class="card-detail power-detail power-detail-${powerSlug(p.power)}"><img class="power-art power-art-${powerSlug(p.power)}" src="${image('powers',p.power)}" alt="${esc(p.power)}"><div><div class="eyebrow">${id===viewerId(state.game)?'Your captain':esc(p.name)}</div><h2>${esc(p.power)}</h2><p class="profile-status">${statusName(p)}</p><blockquote class="card-lore power-lore">${esc(powerLore[p.power])}</blockquote><p>${esc(powerRules[p.power])}</p><p>${shipIcon} ${p.ships} ${p.ships===1?'ship':'ships'}${p.immortal?' · Indestructible':''} · ${p.tokens} tokens${p.protection?` · ${p.protection} protected draws`:''}</p>${powerResultsMarkup(p)}${p.targets.length?`<p>Targets: ${p.targets.map(j=>esc(state.game.players[j].name)).join(' and ')}</p>`:''}<button class="ghost" data-action="power-library">All player powers</button></div></div>`)}
function cardDetail(c,e){const copied=c==='echo'&&e&&e!==c;modal(`<div class="card-detail"><img src="${image('cards',c)}" alt="${esc(cardNames[c])}"><div><div class="eyebrow">${copied?'Collected Echo':'Card almanac'}</div><h2>${esc(cardNames[c])}</h2>${copied?`<section class="echo-copy-detail"><img src="${image('cards',e)}" alt="${esc(cardNames[e])}"><div><span class="eyebrow">COPYING</span><h3>${esc(cardNames[e])}</h3><p>${esc(cardRules[e])}</p></div></section>`:''}<blockquote class="card-lore">${esc(cardLore[c])}</blockquote><p>${esc(cardRules[c])}</p><p style="font-size:13px">In safe waters: treasure adds its printed value; hazards add 50 gold; curses add nothing; other cards add 10 gold. Normal effects do not trigger.</p><button class="ghost" data-action="card-library">All play cards</button></div></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.answer!==undefined)answer(+b.dataset.answer);if(b.dataset.profile!==undefined)profile(+b.dataset.profile);if(b.dataset.secretOwner!==undefined)secretDetail(+b.dataset.secretOwner);if(b.dataset.card)cardDetail(b.dataset.card,b.dataset.effect);const a=b.dataset.action;if(a==='round-speed'&&!b.disabled){if(onlineMode){const current=onlineRoomState?.botSpeed||1;onlineSend({type:'speed',speed:current===1?2:current===2?5:1})}else if(state?.game.players[0].status!=='active'){roundSpeed=nextPlaybackSpeed(roundSpeed);autoRound=state.game.round;setPlaybackSpeed(roundSpeed);b.textContent=roundSpeed===0?'⏸':roundSpeed+'×';b.setAttribute('aria-label',roundSpeed===0?'Paused — resume at 1×':roundSpeed+'× speed — change speed');b.title=roundSpeed===0?'Resume at 1×':'Change speed';scheduleAutoDraw()}}if(b.dataset.quickChat){onlineSend({type:'chat',message:b.dataset.quickChat});$('#overlay-root').innerHTML=''}if(a==='next'&&!presenting){if(state?.request&&!['turn','shared-turn','online-turn','round','round-end'].includes(state.request.kind))showChoice();else answer(0)}if(a==='choice'&&!presenting)showChoice();if(a==='scores')modal(`<div class="eyebrow">Testing view · collected gold</div><h2>The captain’s ledger</h2><p>Current scores. End-game ship and token values have not been added yet.</p>${scoresTable(state.game)}`);if(a==='discard')discardViewer();if(a==='skip'){modal('<h2>Fast-forward this round?</h2><p>Your captain will use its saved bot strategy for the rest of this round. Scores and card effects still resolve normally.</p><div class="action-buttons" style="margin-top:25px"><button class="ghost" data-action="close">Keep playing</button><button class="primary" data-action="confirm-skip">Skip round</button></div>')}if(a==='confirm-skip')answer(0,true);if(a==='leave-game'){modal('<h2>Return to shore?</h2><p>Your voyage is saved in this browser. You can return and resume it later.</p><div class="action-buttons" style="margin-top:25px"><button class="ghost" data-action="close">Keep playing</button><button class="ghost" data-action="confirm-home">Return to shore</button></div>')}if(a==='confirm-home'){$('#overlay-root').innerHTML='';clearTimeout(pollTimer);session=null;intro()}if(a==='new-voyage'){clearTimeout(pollTimer);session=null;lastEvent=0;lastChoice=null;custom=false;offers=[];setup()}if(a==='resume')resume();});
async function resume(){if(busy)return;busy=true;lastEvent=0;lastChoice=null;try{const document=savedVoyage();if(!document)return;const d=await gameCall({type:'resume',document});session=d.id;state=d;lastEvent=Math.max(0,...(d.events||[]).map(e=>e.id));renderGame()}catch(e){session=null;toast(e.message)}finally{busy=false}}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const tool of [{name:'read_voyage',description:'Read the current public game state and the human captain’s legal choices.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({game:state?.game??null,request:state?.request??null,complete:state?.complete??false})},{name:'choose_voyage_action',description:'Complete one currently offered game choice by its zero-based option index. This advances or changes the local voyage.',inputSchema:{type:'object',properties:{requestId:{type:'string'},optionIndex:{type:'integer',minimum:0}},required:['requestId','optionIndex'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(busy||presenting||!state?.request||input.requestId!==state.request.id||!Number.isInteger(input.optionIndex)||!state.request.options[input.optionIndex])throw Error('This choice is unavailable. Read the current voyage first.');await answer(input.optionIndex);return {game:state.game,request:state.request,complete:state.complete}}}])Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}

function blockMarkup(d){if(d.safe)return '';const category=d.safe?(['whirlpool','marooned'].includes(d.card)?'hazard':['coin_curse','idol'].includes(d.card)?'curse':!['coin','crate','diamond','crown'].includes(d.card)?'event':null):d.block?.category;if(!category)return '';return `<div class="card-barrier barrier-${category}"><div class="barrier-orbit"></div><div class="barrier-orbit second"></div><div class="barrier-sparks">${Array.from({length:12},(_,i)=>`<i style="--spark:${i}"></i>`).join('')}</div><div class="barrier-caption"><span>${d.safe?'CALM WATERS':esc(d.block.reason)}</span><strong>${category==='hazard'?'DANGER DEFLECTED':category==='curse'?'CURSE DISSOLVED':'EFFECT DISPELLED'}</strong></div></div>`}
const powerMetricKeys={
'Blood Sailor':['gold','livesGained'],'Cannoneer':['gold'],'Cursed Captain':['gold','goldSaved'],'Ghost Captain':['gold','livesSaved'],
'Marooned Monarch':['gold','goldSaved','livesSaved'],'Mechanic':['gold','livesSaved'],'Merchant':['gold'],'Navigator':['gold','goldSaved','livesSaved'],
'Parrot Whisperer':['gold','goldSaved','livesSaved'],'Sea Witch':['gold','livesSaved','goldTaken'],'Siren Queen':['goldSaved','livesGained','livesSaved'],
'Storm Swindler':['gold','goldTaken'],'Storm Warden':['goldSaved'],'Tempest King':['goldSaved','livesSaved'],
'Tide Watcher':['gold','goldSaved','livesSaved','goldTaken','livesTaken'],'Undead Admiral':['gold','goldTaken']}
const powerMetricLabels={gold:'Gold earned',goldSaved:'Gold saved',livesGained:'Lives gained',livesSaved:'Lives saved',goldTaken:'Gold taken / opponent',livesTaken:'Lives taken / opponent'}
function powerResultsMarkup(p){const r=p.powerResults||{},keys=powerMetricKeys[p.power]||[],metrics=keys.map(key=>`<div><strong>${key.startsWith('gold')?fmt(r[key]):Number(r[key]||0).toLocaleString(undefined,{maximumFractionDigits:2})}</strong><span>${powerMetricLabels[key]}</span></div>`).join('');return `<section class="power-results"><h3>This voyage · power results</h3><div class="power-metrics metric-count-${keys.length}">${metrics}</div>${r.pendingGold?`<p>+${fmt(r.pendingGold)} ${esc(r.pendingLabel||'pending power gold')}.</p>`:''}${r.potAdded?`<p>${fmt(r.potAdded)} extra gold added to the shared pot by doubled treasures.</p>`:''}${r.potPenaltyPrevented?`<p>${fmt(r.potPenaltyPrevented)} gold kept in the pot by blocking your own curses.</p>`:''}${r.rudderGoldSaved?`<p>${fmt(r.rudderGoldSaved)} gold penalties avoided by ignoring Broken Rudder.</p>`:''}${r.othersSaved?`<p>${r.othersSaved} other captains’ lives saved by sold repairs.</p>`:''}<small>Only statistics this power can affect are shown. Gold earned counts power rewards and attributed pot gold actually recovered. Gold saved counts losses prevented, allowing for Escape Ship and Marooned. Gold and lives taken are averages per opponent across the whole game, including opponents who left or were eliminated. These statistics do not change scores.</small></section>`}
let finishPresentation=null,finishPresentationSession=null;
function presentFinish(){
 if(finishPresentationSession===session)return finishPresentation;
 finishPresentationSession=session;
 finishPresentation=(async()=>{presenting=true;lockControls();try{const result=state.game.smoothSailor;if(result){const p=result.player==null?null:state.game.players[result.player];const el=document.createElement('div');el.className='smooth-sailor';el.innerHTML=`<div class="smooth-award"><div class="laurel" aria-hidden="true">${shipIcon}</div><span class="eyebrow">THE SEA HONORS ITS FINEST</span><h2>Smooth Sailor</h2>${p?`<img class="award-captain" src="${image('portraits',p.power)}" alt="${esc(p.power)}"><h3>${esc(p.name)}</h3><p>${result.ships} ships remaining · Most in the fleet</p><strong class="award-gold">+100 GOLD</strong>`:`<h3>A fleet of equals</h3><p>Tied at ${result.ships} ships. No Smooth Sailor bonus is awarded.</p>`}<button class="primary">Reveal the winner <span aria-hidden="true">➜</span></button></div>`;document.body.appendChild(el);tone('harbor');await new Promise(resolve=>el.querySelector('button').onclick=resolve);el.remove()}renderEnd()}catch(error){console.error(error);document.querySelector('.smooth-sailor')?.remove();renderEnd()}finally{presenting=false}})();
 return finishPresentation;
}

document.addEventListener('save-warning',()=>toast('Browser storage is full or unavailable. Keep this tab open to finish your voyage.'));

function secretDetail(id){
 const p=state?.game?.players[id];if(!p?.secret)return;
 if(isPassPlay(state.game)){$('#overlay-root').innerHTML=`<div class="handoff-shield" role="dialog" aria-modal="true"><div class="handoff-card"><img src="${image('portraits',p.power)}" alt=""><span class="eyebrow">PASS THE DEVICE</span><h2>${esc(p.name)}</h2><p>Only ${esc(p.name)} should view Tide Watcher’s secret card.</p><button class="primary" data-action="reveal-tide-secret" data-secret-id="${id}">I’m ${esc(p.name)}</button></div></div>`;return}
 revealSecret(id);
}
function revealSecret(id){
 const p=state?.game?.players[id];if(!p?.secret)return;
 const own=isPassPlay(state.game)||id===viewerId(state.game);modal(`<div class="eyebrow">TIDE WATCHER’S SECRET</div><h2>${own?esc(cardNames[p.secret]):'A hidden card'}</h2><div class="secret-explanation"><img src="${image('cards',own?p.secret:'back')}" alt="${own?esc(cardNames[p.secret]):'Secret card, face down'}"><div><p>Tide Watcher keeps this card out of the deck and can place it on top during a decision window while still in the storm. The next captain to draw receives it.</p><p>${own?esc(cardRules[p.secret]||'This card resolves normally when drawn.'):'Only Tide Watcher knows which card this is. Its identity stays hidden until it is drawn.'}</p><p>It returns to the deck at round end if it has not been played.</p></div></div>`);
}
let spyglassOrdering=null;
let cancelSpyglassDrag=null;
function showSpyglassOrder(r){
 if(spyglassOrdering?.id!==r.id)spyglassOrdering={id:r.id,cards:[...r.cards],order:r.cards.map((_,i)=>i)};
 modal(`<div class="choice-modal spyglass-sort"><div class="eyebrow">YOUR SPYGLASS</div><h2>Arrange the remaining cards</h2><p>Drag cards into the order you want. Read left to right, then the next row: <strong>1 is reached first; the last card goes deepest.</strong> These all return beneath the rest of the deck.</p><p class="sort-hint">Keyboard: focus a card and use the arrow keys to move it.</p><div class="spyglass-grid" aria-label="Order of cards returned to the bottom"></div><div class="sort-actions"><button class="ghost" id="reset-spyglass">Reset order</button><button class="primary" id="confirm-spyglass">Return cards to the deck</button></div><p id="sort-status" role="status"></p></div>`);
 renderSpyglassCards();
 $('#reset-spyglass').onclick=()=>{spyglassOrdering.order=r.cards.map((_,i)=>i);renderSpyglassCards()};
 $('#confirm-spyglass').onclick=async()=>{
  if(busy||state.request?.id!==r.id)return;cancelSpyglassDrag?.();busy=true;
  document.querySelectorAll('.spyglass-sort button').forEach(b=>b.disabled=true);$('#sort-status').textContent='Returning your cards…';
  try{if(onlineMode){onlineSend({type:'spyglassOrder',requestId:r.id,order:[...spyglassOrdering.order]});$('#overlay-root').innerHTML='';spyglassOrdering=null;return}state=await choiceFlow.order(state,[...spyglassOrdering.order],gameCall,d=>state=d);$('#overlay-root').innerHTML='';spyglassOrdering=null;busy=false;renderGame()}
  catch(e){busy=false;toast(e.message);renderGame()}
 };
}
function renderSpyglassCards(){
 cancelSpyglassDrag?.();
 const grid=$('.spyglass-grid');if(!grid)return;
 const old=new Map([...grid.children].map(e=>[e.dataset.sortId,e.getBoundingClientRect()]));
 grid.innerHTML=spyglassOrdering.order.map((id,i)=>`<button type="button" class="spyglass-sort-card" data-sort-id="${id}" aria-label="Position ${i+1}: ${esc(cardNames[spyglassOrdering.cards[id]])}. Use arrow keys to move."><span class="sort-position">${i+1}</span><img src="${image('cards',spyglassOrdering.cards[id])}" alt="${esc(cardNames[spyglassOrdering.cards[id]])}" draggable="false"><span>${esc(cardNames[spyglassOrdering.cards[id]])}</span></button>`).join('');
 for(const el of grid.children){
  const before=old.get(el.dataset.sortId),after=el.getBoundingClientRect();if(before&&!reduced())el.animate([{transform:`translate(${before.x-after.x}px,${before.y-after.y}px)`},{transform:'translate(0,0)'}],{duration:playbackDuration(180),easing:'ease-out'});
  el.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)||busy)return;e.preventDefault();const columns=getComputedStyle(grid).gridTemplateColumns.split(' ').length,from=spyglassOrdering.order.indexOf(+el.dataset.sortId),step=e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:e.key==='ArrowUp'?-columns:columns;moveSpyglassCard(from,Math.max(0,Math.min(spyglassOrdering.order.length-1,from+step)));grid.querySelector(`[data-sort-id="${el.dataset.sortId}"]`)?.focus()};
  el.onpointerdown=e=>{
   if(busy||e.button!==0||e.isPrimary===false)return;
   e.preventDefault();cancelSpyglassDrag?.();
   el.getAnimations().forEach(a=>a.cancel());
   const orderId=spyglassOrdering.id,cardId=+el.dataset.sortId,rect=el.getBoundingClientRect(),ghost=el.cloneNode(true),events=new AbortController();
   ghost.classList.add('spyglass-drag-ghost');ghost.setAttribute('aria-hidden','true');ghost.removeAttribute('data-sort-id');ghost.tabIndex=-1;
   ghost.style.cssText=`position:fixed;width:${rect.width}px;height:${rect.height}px;left:${rect.left}px;top:${rect.top}px;pointer-events:none`;
   document.body.appendChild(ghost);el.classList.add('sort-lifted');let target=spyglassOrdering.order.indexOf(cardId),finished=false;
   const finish=commit=>{
    if(finished)return;finished=true;events.abort();observer.disconnect();ghost.remove();
    el.classList.remove('sort-lifted');[...grid.children].forEach(card=>card.classList.remove('sort-drop-target'));
    cancelSpyglassDrag=null;
    if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);
    if(commit&&grid.isConnected&&spyglassOrdering?.id===orderId){const from=spyglassOrdering.order.indexOf(cardId);if(from>=0&&target>=0)moveSpyglassCard(from,target);}
   };
   cancelSpyglassDrag=()=>finish(false);
   const observer=new MutationObserver(()=>{if(!el.isConnected||!grid.isConnected)finish(false)});
   observer.observe(document.querySelector('#overlay-root'),{childList:true,subtree:true});
   const options={signal:events.signal};
   window.addEventListener('pointermove',m=>{
    if(m.pointerId!==e.pointerId)return;if(m.buttons===0){finish(false);return;}
    ghost.style.left=(m.clientX-rect.width/2)+'px';ghost.style.top=(m.clientY-rect.height/2)+'px';let best=Infinity;
    [...grid.children].forEach((card,i)=>{const b=card.getBoundingClientRect(),d=Math.hypot(m.clientX-(b.x+b.width/2),m.clientY-(b.y+b.height/2));if(d<best){best=d;target=i}});
    [...grid.children].forEach((card,i)=>card.classList.toggle('sort-drop-target',i===target));
   },options);
   window.addEventListener('pointerup',m=>{if(m.pointerId===e.pointerId)finish(true)},options);
   window.addEventListener('pointercancel',m=>{if(m.pointerId===e.pointerId)finish(false)},options);
   el.addEventListener('lostpointercapture',()=>finish(false),options);
   window.addEventListener('blur',()=>finish(false),options);
   document.addEventListener('visibilitychange',()=>{if(document.hidden)finish(false)},options);
   window.addEventListener('keydown',k=>{if(k.key==='Escape')finish(false)},options);
   try{el.setPointerCapture(e.pointerId)}catch{finish(false)}

  };
 }
}
function moveSpyglassCard(from,to){const [id]=spyglassOrdering.order.splice(from,1);spyglassOrdering.order.splice(to,0,id);renderSpyglassCards();$('#sort-status').textContent=`Card moved to position ${to+1}.`;}

// Preview the exact files used by the game, one at a time.

function soundLibrary(){modal(`<h2>Sound preview library</h2><p>Choose any effect or soundtrack to listen.</p><div class="sound-preview-grid">${Object.entries(audioManifest?.sounds||{}).filter(([key])=>!['curse','victory','laugh-spectral-1','laugh-spectral-2','laugh-spectral-3'].includes(key)).map(([key,v])=>`<button class="ghost" data-preview-src="${esc(v.src)}">${esc(({'gloom-1':'Cursed Coin','gloom-2':'Cursed Idol','gloom-3':'Cursed Spoils','parrot':'Parrot squawk','treasure-1':'Glimmering Coin','treasure-2':'Loot Crate','treasure-3':'Diamond Necklace','treasure-4':'Golden Crown','treasure-5':'Lost Fortune'})[key]||key.replaceAll('-',' '))}</button>`).join('')}${[...(playlist?.tracks||[]),playlist?.siren,playlist?.victory,playlist?.loss].filter(Boolean).map(v=>`<button class="ghost" data-preview-src="${esc(v.src)}">${esc(v.title||v.id||v.src.split('/').at(-1))}</button>`).join('')}</div><button class="ghost" data-action="stop-preview">Stop preview</button>`)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='sound-library')soundLibrary();if(a==='audio-credits'){const r=await fetch('assets/audio/credits.html?v=stable-36');modal(`<h2>Audio credits</h2>${await r.text()}`)}if(b.dataset.previewSrc){previewAudio?.pause();[musicTrack,sirenTrack,victoryTrack,lossTrack].forEach(x=>x?.pause());previewAudio=new Audio(b.dataset.previewSrc);previewAudio.volume=soundVolume;previewAudio.onended=()=>syncMusic(state?.game);previewAudio.play().catch(()=>{});}else if(previewAudio&&(a==='stop-preview'||a==='sound'||a==='close')){previewAudio.pause();previewAudio=null;syncMusic(state?.game)}});
document.addEventListener('pointerdown',()=>unlockAudio(),{passive:true});
document.addEventListener('keydown',()=>unlockAudio());

function discardViewer(){const g=state.game;const cards=g.discardView||g.discard.map(c=>({physical:c,effect:c}));modal(`<div class="eyebrow">Public information · oldest to newest</div><h2>Discard pile · ${g.discard.length} cards</h2><p>Faded cards show what was drawn but is held by a captain. They are not discards and cannot return in a Wild Wave.</p><div class="card-gallery discard-history">${cards.map(c=>`<button class="${c.ghost?'ghost-held-card':''}" data-card="${c.physical}" data-effect="${c.effect}"><img src="${image('cards',c.physical)}" alt="${esc(cardNames[c.physical])}">${c.ghost?`<span>Held by ${esc(g.players[c.owner].name)}</span>`:''}${c.draw===g.last?.draw?'<strong>Latest draw</strong>':''}</button>`).join('')}</div>`)}

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&previewAudio){previewAudio.pause();previewAudio=null;syncMusic(state?.game)}});
